WITH with_windows AS (SELECT id, product_name, category, brand, price, cost, stock_qty, launch_date, tags, supplier_id, LAG(price, 1) OVER (PARTITION BY category ORDER BY stock_qty ASC, id ASC) prev_price, LEAD(cost, 1) OVER (PARTITION BY brand ORDER BY launch_date ASC, id ASC) next_cost FROM products) SELECT id, product_name, brand, cost, stock_qty, launch_date, supplier_id, next_cost, CASE WHEN product_name RLIKE '^(Yoga Mat|Noise-Cancel Headphones)$' THEN 'GROUP_B' WHEN product_name RLIKE '^(Laptop Pro 14|wireless mouse)$' THEN 'CORE' ELSE 'EXTENDED' END AS product_name_zone FROM with_windows
